import re

from moler.exceptions import ParsingDone
from moler.helpers import convert_to_number

from ta_moler.cmd.airscale.genericairscale import GenericAirscale


class DbgrrcShow(GenericAirscale):
    """Command dbgrrc show."""

    def __init__(self, connection, options=None, prompt=None, newline_chars=None, runner=None):
        """
        Command dbgrrc show.

        :param options: options name
        :param connection: moler connection to device, terminal when command is executed
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(DbgrrcShow, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.options = options
        self.port = None

        if "port" in self.options:
            self.current_ret["Port"] = {}

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = f"dbgrrc show {self.options}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_port_number(line)
                self._parse_port_number_with_space(line)
                self._parse_port_packets(line)
                self._parse_mac(line)
            except ParsingDone:
                pass
        return super(DbgrrcShow, self).on_new_line(line, is_full_line)

    #   01                              up                            down
    _re_port_number = re.compile(r"^\s*(?P<PORT>\d+)\s+(?P<MODE>\w+)\s+(?P<STATE>\w+)$")

    def _parse_port_number(self, line):
        if self._regex_helper.search_compiled(DbgrrcShow._re_port_number, line):
            self.port = convert_to_number(self._regex_helper.group("PORT"))
            self.current_ret["Port"][self.port] = {}
            self.current_ret["Port"][self.port]["mode"] = self._regex_helper.group("MODE")
            self.current_ret["Port"][self.port]["state"] = self._regex_helper.group("STATE")
            raise ParsingDone

    #   10                      admin down                            down
    _re_port_number_with_space = re.compile(r"^\s*(?P<PORT>\d+)\s+(?P<MODE>\w+?\s\w+)\s+(?P<STATE>\w+)")

    def _parse_port_number_with_space(self, line):
        if self._regex_helper.search_compiled(DbgrrcShow._re_port_number_with_space, line):
            self.port = convert_to_number(self._regex_helper.group("PORT"))
            self.current_ret["Port"][self.port] = {}
            self.current_ret["Port"][self.port]["mode"] = self._regex_helper.group("MODE")
            self.current_ret["Port"][self.port]["state"] = self._regex_helper.group("STATE")
            raise ParsingDone

    #      Rx 64 bytes packets                       4492
    _re_port_packets = re.compile(r"^\s+(?P<PACKET>\w+\s\w+\s\w+\s\w+)\s+(?P<NUMBER>\d+)")

    def _parse_port_packets(self, line):
        if self._regex_helper.search_compiled(DbgrrcShow._re_port_packets, line):
            if "packets" not in self.current_ret["Port"][self.port]:
                self.current_ret["Port"][self.port]["packets"] = {}
            self.current_ret["Port"][self.port]["packets"].update(
                {self._regex_helper.group("PACKET"): convert_to_number(self._regex_helper.group("NUMBER"))}
            )
            raise ParsingDone

    # 02:40:43:80:10:33          Static     218    6190
    _re_mac = re.compile(r"^(?P<MAC>\w{2}:\w{2}:\w{2}:\w{2}:\w{2}:\w{2})\s+(?P<MODE>\w+)\s+(?P<VLAN>\d+)\s+(?P<VALUE>\d+)")

    def _parse_mac(self, line):
        if self._regex_helper.search_compiled(DbgrrcShow._re_mac, line):
            if not self._regex_helper.group("MAC") in self.current_ret:
                self.current_ret[self._regex_helper.group("MAC")] = []
            self.current_ret[self._regex_helper.group("MAC")].append(
                {
                    "Mode": self._regex_helper.group("MODE"),
                    "VLAN": convert_to_number(self._regex_helper.group("VLAN")),
                    "Value": convert_to_number(self._regex_helper.group("VALUE")),
                }
            )
            raise ParsingDone


